92	            keyBytes = state.indexSubspace.packWithVersionstamp(entryKey);
93	        } else {
94	            keyBytes = state.indexSubspace.pack(entryKey);
95	        }
96	        if (remove) {
97	            if (hasIncomplete) {
98	                state.context.removeVersionMutation(keyBytes);
99	            } else {
100	                state.transaction.clear(state.indexSubspace.pack(entryKey));
101	            }
102	            if (state.store.getTimer() != null) {
103	                state.store.getTimer().recordSinceNanoTime(FDBStoreTimer.Events.DELETE_INDEX_ENTRY, startTime);
104	            }
105	        } else {
106	            final byte[] valueBytes = value.pack();
107	            checkKeyValueSizes(savedRecord, valueKey, value, keyBytes, valueBytes);
108	            if (hasIncomplete) {
109	                state.context.addVersionMutation(MutationType.SET_VERSIONSTAMPED_KEY, keyBytes, valueBytes);
110	            } else {
